/**
 * Gamestage UI's own sound set: what the `sounds` registry item installs, and
 * the one call that plays it. GSUI-38.
 *
 *     const sound = createDefaultSoundAdapter({ pick: { rankUp: 2 } })
 *     <GameFeelProvider sound={sound} muted={soundOff}>…</GameFeelProvider>
 *
 * Five cues come in three takes, Tom's call on 2026-10-17 after hearing them:
 * a game keeps the first by default, picks another per cue, or rotates them.
 */
import { createFileSoundAdapter, type FileSoundAdapterOptions, type SoundAdapter } from './sound-adapter'

/** Where the `sounds` item copies its files, served from the app's root. */
export const DEFAULT_SOUND_BASE = '/gamestage/sfx/'

/** Every cue with more than one take, and how many it has. */
export const DEFAULT_SOUND_VARIANTS = {
  correct: 3,
  countdown: 3,
  rankUp: 3,
  reward: 3,
  xp: 3,
} as const

export function createDefaultSoundAdapter(
  options: Partial<Omit<FileSoundAdapterOptions, 'variants'>> = {},
): SoundAdapter {
  return createFileSoundAdapter({
    base: DEFAULT_SOUND_BASE,
    ...options,
    variants: DEFAULT_SOUND_VARIANTS,
  })
}
